<script setup lang="ts">
import { MousePointer2, Sparkles, RotateCcw, ChevronRight, Image as ImageIcon } from 'lucide-vue-next'
import { roleLabels, type ElementInfo, type ElementStyleProperty, type Palette, typefaceStyles, wechatFontStack, normalizeHex } from '@qinbian/shared'
const props=defineProps<{info:ElementInfo|null;computedStyles?:Record<string,string>;palette?:Palette;mappings?:Record<string,string>;fields?:{id:string;label:string}[]}>(),emit=defineEmits<{select:[path:number[]];patch:[patch:any];ai:[];editText:[];media:[]}>()
const colorTarget=ref<'color'|'background-color'|'border-color'|''>(''),sourceOpen=ref(false),draft=ref<Record<string,string>>({}),widthUnit=ref('px')
const name=computed(()=>{const info=props.info;if(!info)return '点选一个元素';return props.fields?.find(f=>f.id===info.field)?.label||(info.chart?'数据图':info.tag==='img'?'图片':info.role!=='none'?roleLabels[info.role]:['section','div'].includes(info.tag)?'容器':'文字')})
const spacing:[ElementStyleProperty,string][]=[['margin-top','上外边距'],['margin-bottom','下外边距'],['margin-left','左外边距'],['margin-right','右外边距'],['padding-top','上内边距'],['padding-bottom','下内边距'],['padding-left','左内边距'],['padding-right','右内边距'],['border-width','边线宽度'],['border-radius','圆角']]
const canRole=computed(()=>!!props.info&&!props.info.chart&&['p','h2','h3','h4','section','div','figcaption','li','td','th'].includes(props.info.tag))
const textElement=computed(()=>!!props.info&&!props.info.chart&&props.info.tag!=='img'&&!!props.info.text.trim())
function refresh(){if(!props.info)return;const c=props.computedStyles||{},own=props.info.styles,font=parseFloat(c['font-size']||own['font-size']||'15');draft.value={...c,...own};for(const k of ['font-size','letter-spacing','margin-top','margin-right','margin-bottom','margin-left','padding-top','padding-right','padding-bottom','padding-left','border-width','border-radius'])draft.value[k]=String(parseFloat(own[k]||c[k]||'0')||0);draft.value['line-height']=String(Number(own['line-height'])||Math.round(parseFloat(c['line-height']||'')/font*100)/100||1.85);draft.value['text-indent']=String(own['text-indent']?.endsWith('em')?parseFloat(own['text-indent']):Math.round(parseFloat(c['text-indent']||'0')/font*100)/100);draft.value.width=own.width&&own.width!=='auto'?String(parseFloat(own.width)):'';draft.value.height=own.height&&own.height!=='auto'?String(parseFloat(own.height)):'';widthUnit.value=own.width?.endsWith('%')?'%':'px';draft.value['text-align']=/^(left|center|right|justify)$/.test(draft.value['text-align']||'')?draft.value['text-align']!:'left';draft.value['font-weight']=/^(400|500|600|700)$/.test(draft.value['font-weight']||'')?draft.value['font-weight']!:'400'}
watch(()=>props.info?.fingerprint,refresh,{immediate:true});watch(()=>props.computedStyles,refresh)
function commit(key:ElementStyleProperty){let value=draft.value[key]||'';if(['font-size','letter-spacing','margin-top','margin-right','margin-bottom','margin-left','padding-top','padding-right','padding-bottom','padding-left','border-width','border-radius','height'].includes(key)&&value!=='')value+='px';if(key==='width'&&value!=='')value+=widthUnit.value;if(key==='text-indent'&&value!=='')value+='em';emit('patch',{styles:{[key]:value}})}
function independent(value:boolean){const styles:Record<string,string>={};if(value&&textElement.value){for(const k of ['font-size','font-weight','font-family','font-style','color'])if(props.computedStyles?.[k])styles[k]=props.computedStyles[k]!;styles['line-height']=draft.value['line-height']!;styles['letter-spacing']=draft.value['letter-spacing']+'px'}emit('patch',{independent:value,...(Object.keys(styles).length?{styles}:{})})}
function fontChoice(){const f=props.info?.styles['font-family']||props.computedStyles?.['font-family']||'';return /Songti|STSong|SimSun/.test(f)?'songti':/STKaiti|KaiTi/.test(f)?'kaiti':f.includes('mp-quote')?'inherit':'heiti'}
function setFont(key:string){emit('patch',{styles:{'font-family':key==='inherit'?wechatFontStack:typefaceStyles[key as keyof typeof typefaceStyles]}})}
function chooseColor(choice:{token?:string;value:string}){const key=colorTarget.value;if(!key)return;emit('patch',{styles:{[key]:choice.value},bindings:choice.token?{[key]:choice.token}:undefined});colorTarget.value=''}
</script>
<template><section class="element-inspector" aria-label="点选属性"><template v-if="info"><div class="element-heading"><span class="eyebrow">当前选中</span><h3>{{name}}<code>{{info.tag}}</code></h3></div><div class="element-breadcrumbs" aria-label="元素层级"><template v-for="(p,i) in info.parents" :key="p.path.join('-')"><ChevronRight v-if="i" :size="10"/><button :class="{active:i===info.parents.length-1}" :aria-label="'选择第'+(i+1)+'层元素'" @click="emit('select',p.path)">{{p.role==='none'?(p.tag==='img'?'图片':['section','div'].includes(p.tag)?'容器':'文字'):roleLabels[p.role]}}</button></template></div><div v-if="info.children.length&&!info.chart" class="inspector-children"><small>深入选择</small><button v-for="child in info.children" :key="child.path.join('-')" :aria-label="'选择内层 '+child.label" @click="emit('select',child.path)">{{child.tag==='img'?'图片':child.label}}</button></div><button class="btn full inspector-ai" @click="emit('ai')"><Sparkles :size="14"/>AI 精细修改这个元素</button><div class="inspector-scope-note">只针对当前选中区域。文字编辑、图片替换仍使用原有编辑功能。</div><div class="inspect-actions"><button v-if="textElement&&!info.chart" class="text-button" @click="emit('editText')">编辑这段文字</button><button v-if="info.tag==='img'" class="text-button" @click="emit('media')"><ImageIcon :size="12"/>替换或裁切</button></div><div class="inspector-profile"><label>全文样式角色<UiSelect :model-value="info.role" :options="[{value:'none',label:'保留原设计'},{value:'body',label:'正文'},{value:'heading',label:'大标题'},{value:'subheading',label:'小标题'},{value:'caption',label:'图注与署名'},{value:'quote',label:'引文'}]" :disabled="!canRole" aria-label="元素文字角色" @change="role=>emit('patch',{role})" compact/></label><button class="inspector-switch" role="switch" aria-label="独立于全文样式" :aria-checked="info.independent" @click="independent(!info.independent)"><i :class="{on:info.independent}"/><span>独立于全文样式</span></button><button class="text-button" @click="emit('patch',{resetOverrides:true})"><RotateCcw :size="11"/>清除文字例外，重新跟随</button></div>
 <template v-if="textElement&&!info.chart"><h4>文字</h4><div class="inspect-grid"><label>字号（px）<input v-model="draft['font-size']" type="number" min="10" max="24" aria-label="元素字号" @change="commit('font-size')"></label><label>行距倍数<input v-model="draft['line-height']" type="number" min="1" max="3" step="0.05" aria-label="元素行距" @change="commit('line-height')"></label><label>字距（px）<input v-model="draft['letter-spacing']" type="number" min="-1" max="6" step="0.5" aria-label="元素字距" @change="commit('letter-spacing')"></label><label>首行缩进（字）<input v-model="draft['text-indent']" type="number" min="0" max="4" step="0.5" aria-label="元素首行缩进" @change="commit('text-indent')"></label><label>对齐<UiSelect v-model="draft['text-align']" :options="[{value:'left',label:'左对齐'},{value:'center',label:'居中'},{value:'right',label:'右对齐'},{value:'justify',label:'两端对齐'}]" aria-label="元素对齐" compact @change="commit('text-align')"/></label><label>字重<UiSelect v-model="draft['font-weight']" :options="[{value:'400',label:'常规'},{value:'500',label:'中等'},{value:'600',label:'半粗'},{value:'700',label:'加粗'}]" aria-label="元素字重" compact @change="commit('font-weight')"/></label></div><label class="inspect-font">字体<UiSelect :model-value="fontChoice()" :options="[{value:'inherit',label:'跟随公众号'},{value:'songti',label:'宋体 · 设备字体'},{value:'heiti',label:'黑体 · 设备字体'},{value:'kaiti',label:'楷体 · 设备字体'}]" aria-label="元素字体" compact @change="setFont"/></label></template>
 <h4>颜色</h4><div class="inspector-colors"><button v-for="c in [{key:'color',label:'文字'},{key:'background-color',label:'底色'},{key:'border-color',label:'边线'}]" :key="c.key" @click="colorTarget=c.key as any"><i :style="{background:normalizeHex(info.styles[c.key]||computedStyles?.[c.key]||'')||'transparent'}"/>{{c.label}}</button></div><h4>尺寸与留白</h4><div class="inspect-grid"><label>宽度<div class="inspect-dimension"><input v-model="draft.width" type="number" min="0" max="680" placeholder="自动" aria-label="元素宽度" @change="commit('width')"><UiSelect v-model="widthUnit" :options="[{value:'px',label:'px'},{value:'%',label:'%'}]" aria-label="宽度单位" compact @change="commit('width')"/></div></label><label>{{info.tag==='img'?'高度随图片比例':'高度（px）'}}<input v-model="draft.height" type="number" min="0" max="1600" placeholder="自动" :disabled="info.tag==='img'" aria-label="元素高度" @change="commit('height')"></label><label v-for="[key,label] in spacing" :key="key">{{label}}（px）<input v-model="draft[key]" type="number" :min="key.startsWith('margin')?-48:0" max="120" :aria-label="'元素'+label" @change="commit(key as ElementStyleProperty)"></label></div><details class="inspect-source"><summary @click="sourceOpen=!sourceOpen">选中元素源码</summary><pre v-if="sourceOpen">{{info.html}}</pre></details><ColorPicker v-if="colorTarget" title="选中元素颜色" :palette="palette" :mappings="mappings" :current="info.styles[colorTarget]" @close="colorTarget=''" @choose="chooseColor"/></template><div v-else class="inspect-empty"><MousePointer2 :size="25"/><h3>点选纸上的一个元素</h3><p>悬停查看边界，点击选中。<br>可沿元素层级向外选择整张卡片。</p></div></section></template>
<style scoped>.element-heading h3{display:flex;align-items:center;justify-content:space-between;font:600 18px var(--serif);color:var(--ink);margin:5px 0 15px}.element-heading code{font:10px ui-monospace,monospace;color:#a4ad97}.element-breadcrumbs{display:flex;align-items:center;gap:4px;flex-wrap:wrap;margin-bottom:18px;color:#a4ae97}.element-breadcrumbs button{font-size:9px;padding:4px 6px;background:#eeeee4;border-radius:2px;color:#8f9c84}.element-breadcrumbs button.active{color:var(--ink);background:#e3ebd8}.inspector-ai{font-size:11px}.inspector-scope-note{font-size:9px;line-height:1.9;color:#a5ad99;margin-top:9px}.inspect-actions{display:flex;gap:17px;margin:9px 0}.inspector-profile{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:17px 0;margin:16px 0}.inspector-profile label,.inspect-grid label,.inspect-font{font-size:9px;color:#929f85;display:grid;gap:6px;min-width:0}.inspector-switch{display:flex;align-items:center;gap:8px;font-size:10px;color:var(--jade);margin:13px 0 7px}.inspector-switch i{width:27px;height:15px;background:#d6ddce;border-radius:10px;position:relative}.inspector-switch i:after{content:'';position:absolute;top:3px;left:3px;width:9px;height:9px;background:#fff;border-radius:50%}.inspector-switch i.on{background:#6f8965}.inspector-switch i.on:after{left:15px}.inspector-profile>.text-button{font-size:9px}.element-inspector h4{font:600 13px var(--serif);color:var(--jade);margin:19px 0 13px}.inspect-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:13px}.inspect-grid input{width:100%;min-width:0;border:1px solid var(--line);border-radius:2px;background:#fdfbf5;padding:7px;font-size:11px}.inspect-font{margin-top:15px}.inspector-colors{display:flex;gap:12px}.inspector-colors button{display:grid;gap:6px;justify-items:center;color:#98a48c;font-size:9px}.inspector-colors i{height:25px;width:42px;border:1px solid var(--line);border-radius:2px}.inspect-dimension{display:flex;gap:4px}.inspect-dimension input{min-width:0;flex:1}.inspect-dimension>.ui-select{width:46px;flex-shrink:0}.inspect-source{margin:22px 0;color:#a0aa93;font-size:9px}.inspect-source pre{max-height:240px;overflow:auto;white-space:pre-wrap;word-break:break-all;font-size:9px;line-height:1.8}.inspect-empty{padding:35px 5px;text-align:center;color:#9eaa90}.inspect-empty svg{margin:auto}.inspect-empty h3{font:600 16px var(--serif);color:var(--jade)}.inspect-empty p{font-size:11px;line-height:2}
</style>

<style scoped>.inspector-children{display:flex;align-items:center;flex-wrap:wrap;gap:5px;margin-bottom:15px;max-height:110px;overflow:auto}.inspector-children small{font-size:9px;color:#9ba98d;width:100%}.inspector-children button{font-size:9px;color:var(--jade);border:1px solid var(--line);padding:4px 6px;border-radius:2px;max-width:100%;text-overflow:ellipsis;overflow:hidden;white-space:nowrap}</style>
